def convert_base_to_base(s, from_base, to_base):
    if s == '0':
        return '0'
    if from_base == 10:
        num = int(s)
    else:
        num = int(s, from_base)
    if to_base == 10:
        return str(num)
    digits = []
    while num > 0:
        rem = num % to_base
        if rem < 10:
            digits.append(str(rem))
        else:
            digits.append(chr(ord('a') + rem - 10))
        num = num // to_base
    return ''.join(reversed(digits))
```

