def reorder_by_priority_groups(items, category_of, priority):
    # Create a list for each priority category and a list for unclassified items
    groups = {cat: [] for cat in priority}
    others = []

    # Group items by their category
    for item in items:
        cat = category_of.get(item)
        if cat in groups:
            groups[cat].append(item)
        else:
            others.append(item)

    # Concatenate the groups in priority order, then add the unclassified items
    result = []
    for cat in priority:
        result.extend(groups[cat])
    result.extend(others)
    return result
```

